#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn basic() {
        assert_eq!(trapped_water(&[3, 0, 2, 0, 4]), 7);
    }

    #[test]
    fn classic() {
        assert_eq!(trapped_water(&[0, 1, 0, 2, 1, 0, 1, 3, 2, 1, 2, 1]), 6);
    }

    #[test]
    fn empty_and_tiny() {
        assert_eq!(trapped_water(&[]), 0);
        assert_eq!(trapped_water(&[5]), 0);
        assert_eq!(trapped_water(&[2, 1]), 0);
    }

    #[test]
    fn monotonic() {
        assert_eq!(trapped_water(&[1, 2, 3, 4]), 0);
        assert_eq!(trapped_water(&[4, 3, 2, 1]), 0);
    }

    #[test]
    fn large_basin() {
        let mut h = vec![100000u32];
        h.extend(std::iter::repeat(0).take(100000));
        h.push(100000);
        assert_eq!(trapped_water(&h), 100000u64 * 100000);
    }
}
